       'Owner approved 2026-11-15: current booking, pricing and refund rules; electronic consent'
where not exists (
  select 1 from sys_notice where notice_title=0xe8a28be9bca0e99d92e5b9b4e69785e8a18cc2b7e69785e5b185e688bfe6ba90e4b88ae69eb6e4b88ee9a284e8aea2e59088e4bd9ce58d8fe8aeae
    and (coalesce(status,'')<>'1' or coalesce(sha2(notice_content,256),'')<>'a63cfa54158fa38a52e428f9f24f2fa3606a00e2976dde98b32bddb3c83aa55e')
